package com.termux.app.workspace;

import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import android.text.*;import android.text.style.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentMarkdownTest {
 private Activity activity;@Before public void setup(){activity=Robolectric.buildActivity(Activity.class).setup().get();}
 private String text(View v){if(v instanceof TextView)return ((TextView)v).getText().toString();StringBuilder b=new StringBuilder();if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)b.append(text(g.getChildAt(i))).append('\n');}return b.toString();}
 @Test public void proseRendersFormattingAndReadOnlyTaskLists(){Spanned s=AgentMarkdown.create(activity).toMarkdown("## Heading\n\n**bold**, *italic*, ~~gone~~ and `code`\n\n- [x] done\n- [ ] pending");assertFalse(s.toString().contains("##"));assertTrue(s.toString().contains("Heading"));assertTrue(s.toString().contains("☑ done"));assertTrue(s.toString().contains("☐ pending"));String spans=java.util.Arrays.toString(java.util.Arrays.stream(s.getSpans(0,s.length(),Object.class)).map(x->x.getClass().getSimpleName()).toArray());assertTrue(spans,spans.contains("StrongEmphasisSpan"));assertTrue(spans,spans.contains("StrikethroughSpan"));}
 @Test public void copyKeepsExactCodeWithoutLineNumbersOrTaskConversion(){AgentMarkdownView v=new AgentMarkdownView(activity);String code="- [x] literal\nprint('Привет')\n";v.update("Codex","```python\n"+code+"```",null);TextView content=v.findViewWithTag("markdown-code");assertEquals(code,content.getText().toString());v.findViewWithTag("markdown-copy").performClick();android.content.ClipboardManager c=(android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE);assertEquals(code,c.getPrimaryClip().getItemAt(0).getText().toString());}
 @Test public void streamingKeepsEarlierBlocksAndCodeViewIdentity(){AgentMarkdownView v=new AgentMarkdownView(activity);v.update("Codex","## Ready\n\n```py\nprint(1)",null);View heading=v.getChildAt(1),code=v.findViewWithTag("markdown-code");v.update("Codex","## Ready\n\n```py\nprint(12)\n```",null);assertSame(heading,v.getChildAt(1));assertSame(code,v.findViewWithTag("markdown-code"));assertEquals("print(12)\n",((TextView)code).getText().toString());}
 @Test public void tablesHaveHorizontalViewportAndActualCellText(){AgentMarkdownView v=new AgentMarkdownView(activity);v.update("Codex","| Name | Size |\n| --- | ---: |\n| part.stl | 42 KB |",null);assertTrue(v.getChildAt(1) instanceof HorizontalScrollView);String shown=text(v);assertTrue(shown,shown.contains("Name"));assertTrue(shown,shown.contains("part.stl"));assertTrue(shown,shown.contains("42 KB"));}
 @Test public void longCodeCanExpandAndWholeBlockCanBeCopied(){AgentMarkdownView v=new AgentMarkdownView(activity);String code="echo hello\n".repeat(30);v.update("Codex","```bash\n"+code+"```",null);TextView body=v.findViewWithTag("markdown-code");assertEquals(12,body.getMaxLines());v.findViewWithTag("markdown-expand").performClick();assertEquals(Integer.MAX_VALUE,body.getMaxLines());v.findViewWithTag("markdown-copy").performClick();assertEquals(code,((android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip().getItemAt(0).getText().toString());}
 @Test public void syntaxScannerPreservesLongMalformedStrings(){String source="\""+"a".repeat(20000)+"\\";assertEquals(source,AgentMarkdown.highlight(source,"python").toString());}
 @Test public void linkResolverAllowsOnlyExplicitWebNavigation(){View v=new View(activity);for(String link:new String[]{"javascript:alert(1)","file:///root/key","intent://settings","data:text/html,x"})AgentMarkdown.openLink(v,link);assertNull(Shadows.shadowOf(activity).getNextStartedActivity());AgentMarkdown.openLink(v,"https://example.org/docs");assertEquals("https://example.org/docs",Shadows.shadowOf(activity).getNextStartedActivity().getDataString());}
}
